"""Turn your results files into the 2 x 2 comparison for Step 5 and your report. Do not edit.

    python -m harness.summarize --group G07 --split dev
    python -m harness.summarize --group G07 --split dev --latex > report/table_2x2.tex

For each of your four versions it averages the 3 seeds and gives a 95% bootstrap
confidence interval (resampling conversations). It also reports:
  memory effect      = (your memory) - (M0), with the same training
  training effect    = (your training) - (A0), with the same memory
  interaction        = (both) - (memory only) - (training only) + (baseline)
"""
from __future__ import annotations

import argparse
import csv
import random
from collections import defaultdict

from .common import ROOT, load_config
from .metrics import aggregate

METRICS = ["score", "accuracy", "citation_f1", "abstain_f1", "memory_recall", "tokens_per_turn"]


def load(group: str, split: str) -> dict[str, dict[int, list[dict]]]:
    cfg = load_config()
    data: dict[str, dict[int, list[dict]]] = defaultdict(dict)
    for fp in sorted((ROOT / cfg["paths"]["results_dir"]).glob(f"{group}_*_{split}_s*.csv")):
        with open(fp, encoding="utf-8") as f:
            rows = list(csv.DictReader(f))
        if rows:
            data[rows[0]["config"]][int(rows[0]["seed"])] = rows
    return data


def summarize_config(seed_rows: dict[int, list[dict]], weights, base_tok, picks: list[list[str]]):
    """picks: the SAME bootstrap resamples of session ids for every version, so effects are paired."""
    n_boot = len(picks)
    point = {m: sum(aggregate(r, weights, base_tok)[m] for r in seed_rows.values()) / len(seed_rows) for m in METRICS}
    sessions = sorted({r["session_id"] for rows in seed_rows.values() for r in rows})
    by_sess = {s: {seed: [r for r in rows if r["session_id"] == s] for seed, rows in seed_rows.items()} for s in sessions}
    boots = defaultdict(list)
    for pick in picks:
        pick = [s for s in pick if s in by_sess]
        vals = defaultdict(float)
        for seed in seed_rows:
            rows = [r for s in pick for r in by_sess[s][seed]]
            agg = aggregate(rows, weights, base_tok)
            for m in METRICS:
                vals[m] += agg[m] / len(seed_rows)
        for m in METRICS:
            boots[m].append(vals[m])
    ci = {m: (sorted(boots[m])[int(0.025 * n_boot)], sorted(boots[m])[int(0.975 * n_boot) - 1]) for m in METRICS}
    return point, ci, boots


def main(argv=None):
    p = argparse.ArgumentParser(description="2 x 2 summary with bootstrap CIs")
    p.add_argument("--group", required=True)
    p.add_argument("--split", default="dev")
    p.add_argument("--boot", type=int, default=1000)
    p.add_argument("--latex", action="store_true")
    a = p.parse_args(argv)
    cfg = load_config()
    data = load(a.group, a.split)
    if not data:
        raise SystemExit("No results found. Run harness.evaluate first.")
    base_tok = None
    if "M0+A0" in data:
        base_tok = sum(aggregate(r, cfg["scoring"]["weights"])["tokens_per_turn"] for r in data["M0+A0"].values()) / len(data["M0+A0"])
    rng = random.Random(0)
    all_sessions = sorted({r["session_id"] for sr in data.values() for rows in sr.values() for r in rows})
    picks = [[rng.choice(all_sessions) for _ in all_sessions] for _ in range(a.boot)]
    res = {c: summarize_config(s, cfg["scoring"]["weights"], base_tok, picks) for c, s in sorted(data.items())}

    if a.latex:
        print("% generated by harness.summarize -- paste into the template's results table")
        for c, (pt, ci, _) in res.items():
            cells = " & ".join(f"{pt[m]:.2f} [{ci[m][0]:.2f}, {ci[m][1]:.2f}]" for m in METRICS[:5])
            print(f"{c} & {cells} & {pt['tokens_per_turn']:.0f} \\\\")
    else:
        print(f"{'config':8} " + " ".join(f"{m:>26}" for m in METRICS))
        for c, (pt, ci, _) in res.items():
            print(f"{c:8} " + " ".join(f"{pt[m]:8.3f} [{ci[m][0]:7.3f},{ci[m][1]:7.3f}]" for m in METRICS))
        print(f"seeds per config: { {c: sorted(s) for c, s in data.items()} }")

    mems = {c.split("+")[0] for c in data} - {"M0"}
    ads = {c.split("+")[1] for c in data} - {"A0"}
    if len(mems) == 1 and len(ads) == 1 and len(data) == 4:
        m, t = mems.pop(), ads.pop()
        b, mo, to, both = (res[k][2]["score"] for k in ("M0+A0", f"{m}+A0", f"M0+{t}", f"{m}+{t}"))
        def eff(xs):
            xs = sorted(xs)
            return sum(xs) / len(xs), xs[int(0.025 * len(xs))], xs[int(0.975 * len(xs)) - 1]
        mem_eff = eff([(x2 - x0 + x3 - x1) / 2 for x0, x1, x2, x3 in zip(b, to, mo, both)])
        trn_eff = eff([(x1 - x0 + x3 - x2) / 2 for x0, x1, x2, x3 in zip(b, to, mo, both)])
        inter = eff([x3 - x2 - x1 + x0 for x0, x1, x2, x3 in zip(b, to, mo, both)])
        tag = "%" if a.latex else ""
        print(f"{tag}memory effect ({m}):    {mem_eff[0]:+.2f} points, 95% CI [{mem_eff[1]:+.2f}, {mem_eff[2]:+.2f}]")
        print(f"{tag}training effect ({t}):  {trn_eff[0]:+.2f} points, 95% CI [{trn_eff[1]:+.2f}, {trn_eff[2]:+.2f}]")
        print(f"{tag}interaction:            {inter[0]:+.2f} points, 95% CI [{inter[1]:+.2f}, {inter[2]:+.2f}]")
    else:
        print("(effects are shown once all four versions have results)")


if __name__ == "__main__":
    main()
